package broker;

import server.ClientConnection;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class Broker {
    private static final Logger logger = Logger.getLogger(Broker.class.getName());
    private final Map<String, Topic> topics = new ConcurrentHashMap<>();

    public Topic subscribe(String topic, ClientConnection connection) {
        Topic t = topics.computeIfAbsent(topic, Topic::new);
        t.addSubscriber(connection);

        return t;
    }

    public void unsubscribe(String topic, ClientConnection connection) {
        topics.computeIfPresent(topic, (_t, topicObj) -> {
            topicObj.removeSubscriber(connection);
            return topicObj.canBeRemoved() ? null : topicObj;
        });
    }

    public void unsubscribeAll(ClientConnection connection) {
        for (String topic : topics.keySet()) {
            unsubscribe(topic, connection);
        }
    }

    public void publish(String topic, byte[] payload) {
        Topic t = topics.get(topic);
        if (t == null) return;

        for (ClientConnection connection : t.getSubscribers()) {
            try {
                connection.sendMessage(topic, payload);
            } catch (IOException e) {
                logger.warning("failed to send notification to client (ID: %s): %s".formatted(connection.getId(), e.getMessage()));
            }
        }
    }

    public String[] listTopics() {
        return topics.keySet().toArray(new String[0]);
    }
}

package broker;

import server.ClientConnection;

import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.logging.Logger;

public class Broker {
    private static final Logger logger = Logger.getLogger(Broker.class.getName());
    private final Map<String, Topic> topics = new ConcurrentHashMap<>();

    public Topic subscribe(String topic, ClientConnection connection) {
        Topic t = topics.computeIfAbsent(topic, Topic::new);
        t.addSubscriber(connection);

        return t;
    }

    public void unsubscribe(String topic, ClientConnection connection) {
        topics.computeIfPresent(topic, (_t, topicObj) -> {
            topicObj.removeSubscriber(connection);
            return topicObj.canBeRemoved() ? null : topicObj;
        });
    }

    public void unsubscribeAll(ClientConnection connection) {
        for (String topic : topics.keySet()) {
            unsubscribe(topic, connection);
        }
    }

    public void publish(String topic, byte[] payload, boolean retain) {
        Topic t = topics.get(topic);

        if (retain) {
            if (payload.length == 0) {
                if (t != null) {
                    t.clearRetainedMessage();
                    if (t.canBeRemoved()) {
                        topics.remove(topic, t);
                        t = null;
                    }
                }
            } else {
                t = topics.computeIfAbsent(topic, Topic::new);
                t.setRetainedMessage(payload);
            }
        }

        if (t == null) return;

        for (ClientConnection connection : t.getSubscribers()) {
            try {
                connection.sendMessage(topic, payload);
            } catch (IOException e) {
                logger.warning("failed to send notification to client (ID: %s): %s".formatted(connection.getId(), e.getMessage()));
            }
        }
    }

    public String[] listTopics() {
        return topics.keySet().toArray(new String[0]);
    }
}

package broker;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

class TopicTest {

    @Test
    void retainedMessageIsStoredAndReturnedAsDefensiveCopies() {
        Topic topic = new Topic("weather");
        byte[] retained = new byte[]{1, 2, 3};

        topic.setRetainedMessage(retained);
        retained[0] = 9;

        byte[] firstRead = topic.getRetainedMessage();
        assertArrayEquals(new byte[]{1, 2, 3}, firstRead);

        firstRead[1] = 8;
        byte[] secondRead = topic.getRetainedMessage();
        assertArrayEquals(new byte[]{1, 2, 3}, secondRead);
    }

    @Test
    void addAndRemoveSubscriberUpdatesMembership() {
        Topic topic = new Topic("weather");

        topic.addSubscriber("client-1");
        assertTrue(topic.getSubscribers().contains("client-1"));

        topic.removeSubscriber("client-1");
        assertFalse(topic.getSubscribers().contains("client-1"));
    }

    @Test
    void canBeRemovedOnlyWhenNoSubscribersAndNoRetainedMessage() {
        Topic topic = new Topic("weather");

        assertTrue(topic.canBeRemoved());

        topic.addSubscriber("client-1");
        assertFalse(topic.canBeRemoved());

        topic.removeSubscriber("client-1");
        topic.setRetainedMessage(new byte[]{7});
        assertFalse(topic.canBeRemoved());

        topic.clearRetainedMessage();
        assertTrue(topic.canBeRemoved());
    }
}

package command;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import server.ClientConnection;
import services.analytics.AnalyticsService;
import services.analytics.AnalyticsSnapshot;

import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.nio.charset.StandardCharsets;
import java.util.Map;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class AnalyticsCommandTest {
    private static final ObjectMapper MAPPER = new ObjectMapper();

    @Test
    void executeSerializesSnapshotToJson() throws Exception {
        AnalyticsService analyticsService = mock(AnalyticsService.class);
        AnalyticsSnapshot snapshot = new AnalyticsSnapshot(
                1000L,
                1L,
                2L,
                3L,
                4L,
                5L,
                6L,
                Map.of("weather", 7L),
                Map.of("weather", 8L),
                Map.of("PUBLISH", 9L)
        );
        when(analyticsService.getSnapshot()).thenReturn(snapshot);

        AnalyticsCommand command = new AnalyticsCommand(analyticsService);
        ClientConnection connection = mock(ClientConnection.class);

        byte[] response = command.execute(connection, new DataInputStream(new ByteArrayInputStream(new byte[0])));
        JsonNode json = MAPPER.readTree(new String(response, StandardCharsets.UTF_8));

        assertEquals(1L, json.get("totalPublishes").asLong());
        assertEquals(7L, json.get("publishCountByTopic").get("weather").asLong());
        assertEquals(9L, json.get("commandCountByType").get("PUBLISH").asLong());
    }
}

package command;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;

class CommandCodeTest {

    @Test
    void valueOfReturnsExpectedCommandCode() {
        assertEquals(CommandCode.SUBSCRIBE, CommandCode.valueOf((byte) 0x01));
        assertEquals(CommandCode.UNSUBSCRIBE, CommandCode.valueOf((byte) 0x02));
        assertEquals(CommandCode.PUBLISH, CommandCode.valueOf((byte) 0x03));
        assertEquals(CommandCode.LIST, CommandCode.valueOf((byte) 0x04));
        assertEquals(CommandCode.ANALYTICS, CommandCode.valueOf((byte) 0x05));
    }

    @Test
    void valueOfThrowsForUnknownCode() {
        assertThrows(CommandException.class, () -> CommandCode.valueOf((byte) 0x7F));
    }
}

package command;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.mockito.Mockito.mock;

class CommandRegistryTest {

    @Test
    void registerAndGetReturnsSameCommandInstance() {
        CommandRegistry registry = new CommandRegistry();
        Command command = mock(Command.class);

        registry.register(CommandCode.LIST, command);

        assertSame(command, registry.get(CommandCode.LIST));
    }

    @Test
    void getThrowsWhenCommandNotRegistered() {
        CommandRegistry registry = new CommandRegistry();

        assertThrows(CommandException.class, () -> registry.get(CommandCode.ANALYTICS));
    }
}

package command;

import broker.Broker;
import org.junit.jupiter.api.Test;
import server.ClientConnection;

import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.nio.charset.StandardCharsets;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

class ListCommandTest {

    @Test
    void executeReturnsCommaSeparatedTopicList() {
        Broker broker = mock(Broker.class);
        when(broker.listTopics()).thenReturn(new String[]{"weather", "news"});

        ListCommand command = new ListCommand(broker);
        ClientConnection connection = mock(ClientConnection.class);

        byte[] response = command.execute(connection, new DataInputStream(new ByteArrayInputStream(new byte[0])));

        assertEquals("weather, news", new String(response, StandardCharsets.UTF_8));
    }
}

package command;

import broker.Broker;
import org.junit.jupiter.api.Test;
import server.ClientConnection;
import services.analytics.AnalyticsService;

import java.io.ByteArrayInputStream;
import java.io.ByteArrayOutputStream;
import java.io.DataInputStream;
import java.io.DataOutputStream;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;

class PublishCommandTest {

    @Test
    void executePublishesPayloadAndRecordsAnalytics() throws Exception {
        Broker broker = mock(Broker.class);
        AnalyticsService analyticsService = mock(AnalyticsService.class);
        ClientConnection connection = mock(ClientConnection.class);
        PublishCommand command = new PublishCommand(broker, analyticsService);

        byte[] payload = "sunny".getBytes();
        DataInputStream input = publishPayload("weather", true, payload);

        byte[] response = command.execute(connection, input);

        verify(broker).publish(eq("weather"), eq(payload), eq(true));
        verify(analyticsService).recordPublish("weather");
        assertEquals(0, response.length);
        assertArrayEquals(new byte[0], response);
    }

    private static DataInputStream publishPayload(String topic, boolean retain, byte[] payload) throws Exception {
        ByteArrayOutputStream raw = new ByteArrayOutputStream();
        DataOutputStream out = new DataOutputStream(raw);
        out.writeUTF(topic);
        out.writeBoolean(retain);
        out.write(payload);
        return new DataInputStream(new ByteArrayInputStream(raw.toByteArray()));
    }
}

package command;

import broker.Broker;
import broker.Topic;
import org.junit.jupiter.api.Test;
import server.ClientConnection;
import services.analytics.AnalyticsService;

import java.io.ByteArrayInputStream;
import java.io.DataInputStream;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

class SubscribeCommandTest {

    @Test
    void executeSubscribesClientAndReturnsRetainedMessage() throws Exception {
        Broker broker = mock(Broker.class);
        AnalyticsService analyticsService = mock(AnalyticsService.class);
        SubscribeCommand command = new SubscribeCommand(broker, analyticsService);

        ClientConnection connection = mock(ClientConnection.class);
        UUID clientId = UUID.randomUUID();
        when(connection.getId()).thenReturn(clientId);

        Topic topic = mock(Topic.class);
        byte[] retained = "retained".getBytes(StandardCharsets.UTF_8);
        when(topic.getRetainedMessage()).thenReturn(retained);
        when(broker.subscribe("weather", clientId.toString())).thenReturn(topic);

        DataInputStream in = new DataInputStream(new ByteArrayInputStream("weather".getBytes(StandardCharsets.UTF_8)));
        byte[] response = command.execute(connection, in);

        verify(broker).subscribe(eq("weather"), eq(clientId.toString()));
        verify(analyticsService).recordSubscribe("weather");
        assertArrayEquals(retained, response);
    }

    @Test
    void executeReturnsEmptyArrayWhenNoRetainedMessageExists() throws Exception {
        Broker broker = mock(Broker.class);
        AnalyticsService analyticsService = mock(AnalyticsService.class);
        SubscribeCommand command = new SubscribeCommand(broker, analyticsService);

        ClientConnection connection = mock(ClientConnection.class);
        UUID clientId = UUID.randomUUID();
        when(connection.getId()).thenReturn(clientId);

        Topic topic = mock(Topic.class);
        when(topic.getRetainedMessage()).thenReturn(null);
        when(broker.subscribe("weather", clientId.toString())).thenReturn(topic);

        DataInputStream in = new DataInputStream(new ByteArrayInputStream("weather".getBytes(StandardCharsets.UTF_8)));
        byte[] response = command.execute(connection, in);

        assertArrayEquals(new byte[0], response);
    }
}

